package com.chengyinhub.web.controller.api;

import com.chengyinhub.business.mapper.PersonalExplorationExportMapper;
import com.chengyinhub.business.service.PersonalExplorationExportService;
import com.chengyinhub.common.exception.ServiceException;
import org.junit.jupiter.api.Test;
import java.nio.charset.StandardCharsets;
import java.time.OffsetDateTime;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class PersonalExplorationExportServiceTest {
    private final PersonalExplorationExportMapper mapper=mock(PersonalExplorationExportMapper.class);
    private long clock=OffsetDateTime.parse("2026-10-12T12:00:00+08:00").toInstant().toEpochMilli();
    private final PersonalExplorationExportService service=new PersonalExplorationExportService(mapper){@Override protected long now(){return clock;}};
    private Map<String,Object> prepare(int count,int size){when(mapper.upper(anyLong(),anyString(),anyString(),anyString())).thenReturn(count==0?0L:9L);when(mapper.boundedCount(anyLong(),anyString(),anyString(),anyString(),anyLong())).thenReturn(count);return service.prepare(41L,"2026-10-01","2026-10-13",size);}
    private Map<String,Object> row(long id){Map<String,Object> r=new HashMap<>();r.put("recordId",id);r.put("completedAt","2026-10-12T10:00:00.000+08:00");r.put("routeVersion",2L);r.put("elapsedSeconds",3600L);r.put("routeAvailability","AVAILABLE");r.put("routeTitle","河岸");r.put("stateJson","DO NOT EXPORT");return r;}
    @Test void prepareFreezesShanghaiWallBoundsAndLongStringUpper(){Map<String,Object> out=prepare(2,1);assertEquals("9",out.get("upperRecordId"));assertEquals(2,out.get("expectedRows"));assertEquals(clock,out.get("asOfMs"));verify(mapper).boundedCount(41L,"2026-10-01 00:00:00","2026-10-13 00:00:00","2026-10-12 12:00:00.000",9L);}
    @Test void stableKeysetAndExactTerminalCount(){String first=(String)prepare(2,1).get("cursor");when(mapper.page(41L,41L,"2026-10-01 00:00:00","2026-10-13 00:00:00","2026-10-12 12:00:00.000",9L,null,2)).thenReturn(Arrays.asList(row(9),row(8)));Map<String,Object> one=service.page(41L,first);assertEquals(false,one.get("complete"));String second=(String)one.get("nextCursor");when(mapper.page(41L,41L,"2026-10-01 00:00:00","2026-10-13 00:00:00","2026-10-12 12:00:00.000",9L,9L,2)).thenReturn(Collections.singletonList(row(8)));Map<String,Object> two=service.page(41L,second);assertEquals(true,two.get("complete"));assertEquals(2,two.get("emittedRows"));assertNull(two.get("nextCursor"));assertEquals(one.get("snapshotId"),two.get("snapshotId"));}
    @Test void maximumRowCapRejectsInsteadOfTruncating(){when(mapper.upper(anyLong(),anyString(),anyString(),anyString())).thenReturn(2000L);when(mapper.boundedCount(anyLong(),anyString(),anyString(),anyString(),anyLong())).thenReturn(1001);assertThrows(ServiceException.class,()->service.prepare(41L,"2026-10-01","2026-10-13",100));}
    @Test void foreignOwnerCannotReuseCursor(){String cursor=(String)prepare(1,1).get("cursor");clearInvocations(mapper);assertThrows(ServiceException.class,()->service.page(42L,cursor));verifyNoInteractions(mapper);}
    @Test void nonCanonicalOrUnknownCursorVersionRejected(){String cursor=(String)prepare(1,1).get("cursor");String raw=new String(Base64.getUrlDecoder().decode(cursor),StandardCharsets.US_ASCII);for(String bad:new String[]{"2"+raw.substring(1),raw.replace("|41|","|041|"),raw+"|extra"})assertThrows(ServiceException.class,()->service.page(41L,Base64.getUrlEncoder().withoutPadding().encodeToString(bad.getBytes(StandardCharsets.US_ASCII))));assertThrows(ServiceException.class,()->service.page(41L,cursor+"="));}
    @Test void sourceCountChangeReturnsExplicitIncompleteWithoutRows(){String cursor=(String)prepare(2,1).get("cursor");when(mapper.boundedCount(anyLong(),anyString(),anyString(),anyString(),anyLong())).thenReturn(1);Map<String,Object> out=service.page(41L,cursor);assertEquals("SOURCE_CHANGED",out.get("state"));assertEquals(false,out.get("complete"));assertTrue(((List<?>)out.get("items")).isEmpty());verify(mapper,never()).page(anyLong(),anyLong(),anyString(),anyString(),anyString(),anyLong(),any(),anyInt());}
    @Test void earlyExhaustionCannotClaimComplete(){String cursor=(String)prepare(2,2).get("cursor");when(mapper.page(anyLong(),anyLong(),anyString(),anyString(),anyString(),anyLong(),any(),anyInt())).thenReturn(Collections.singletonList(row(9)));assertEquals("SOURCE_CHANGED",service.page(41L,cursor).get("state"));}
    @Test void hiddenTitleAndRawRuntimeAreExplicitlyExcluded(){String cursor=(String)prepare(1,1).get("cursor");Map<String,Object> record=row(9);record.put("routeAvailability","UNAVAILABLE");when(mapper.page(anyLong(),anyLong(),anyString(),anyString(),anyString(),anyLong(),any(),anyInt())).thenReturn(Collections.singletonList(record));Map<?,?> exported=(Map<?,?>)((List<?>)service.page(41L,cursor).get("items")).get(0);assertNull(exported.get("routeTitle"));assertFalse(exported.containsKey("stateJson"));assertEquals("9",exported.get("recordId"));}
    @Test void expiredAndFutureCursorCannotBeUsed(){String cursor=(String)prepare(1,1).get("cursor");clock+=86400001L;assertThrows(ServiceException.class,()->service.page(41L,cursor));clock-=86400002L;assertThrows(ServiceException.class,()->service.page(41L,cursor));}
    @Test void emptyPeriodIsCompleteWithoutDroppingAnything(){String cursor=(String)prepare(0,10).get("cursor");when(mapper.page(anyLong(),anyLong(),anyString(),anyString(),anyString(),anyLong(),any(),anyInt())).thenReturn(Collections.emptyList());Map<String,Object> out=service.page(41L,cursor);assertEquals("COMPLETE",out.get("state"));assertEquals(0,out.get("emittedRows"));assertEquals(true,out.get("complete"));}
    @Test void unknownGateOrOutOfOrderMapperRowsFailClosed(){String cursor=(String)prepare(2,2).get("cursor");Map<String,Object> invalid=row(9);invalid.put("routeAvailability","MAYBE");when(mapper.page(anyLong(),anyLong(),anyString(),anyString(),anyString(),anyLong(),any(),anyInt())).thenReturn(Arrays.asList(invalid,row(8)));assertThrows(IllegalStateException.class,()->service.page(41L,cursor));when(mapper.page(anyLong(),anyLong(),anyString(),anyString(),anyString(),anyLong(),any(),anyInt())).thenReturn(Arrays.asList(row(8),row(9)));assertThrows(IllegalStateException.class,()->service.page(41L,cursor));}
    @Test void invalidDatesFutureRangeAndBadPageSizeNeverQuery(){for(String[] range:new String[][]{{"2026-02-30","2026-03-01"},{"2025-01-01","2026-10-13"},{"2026-10-13","2026-10-14"}})assertThrows(ServiceException.class,()->service.prepare(41L,range[0],range[1],1));assertThrows(ServiceException.class,()->service.prepare(41L,"2026-10-01","2026-10-13",101));verifyNoInteractions(mapper);}
    @Test void longMaxRecordIdIsNeverRounded(){when(mapper.upper(anyLong(),anyString(),anyString(),anyString())).thenReturn(Long.MAX_VALUE);when(mapper.boundedCount(anyLong(),anyString(),anyString(),anyString(),anyLong())).thenReturn(1);String cursor=(String)service.prepare(41L,"2026-10-01","2026-10-13",1).get("cursor");when(mapper.page(anyLong(),anyLong(),anyString(),anyString(),anyString(),anyLong(),any(),anyInt())).thenReturn(Collections.singletonList(row(Long.MAX_VALUE)));Map<?,?> record=(Map<?,?>)((List<?>)service.page(41L,cursor).get("items")).get(0);assertEquals("9223372036854775807",record.get("recordId"));}
}
